        f.add(txt(ctl.scene, colYou, f.y, fmtVP(me.parts[key2]), { size: 14, origin: [1, 0] }));
        f.add(txt(ctl.scene, colFoe, f.y, fmtVP(foe.parts[key2]), { size: 14, origin: [1, 0] }));
